type ReadingKind = 'day' | 'month' | 'period';
export interface AstroReading { theme: string; focus: string; overview: string; lead: string; nuance: string; paragraphs: string[]; sourceKeys: string[] }
type Material = readonly [theme: string, focus: string, text: string, continuation: string];

// Each pair has its own subject and practical development. Aspect language supplies
// the relationship between those themes, rather than a forecast of an outcome.
const pairs: Record<string, Material> = {
  'sun:moon': ['Reconhecer o que sustenta você', 'relação entre vontade e acolhimento', 'A vontade de seguir adiante poderá pedir uma conversa com aquilo que faz você se sentir em casa. Observe como suas escolhas públicas convivem com necessidades mais reservadas. Dar nome a essa diferença poderá ajudar a reconhecer o que merece espaço.', 'Uma rotina possível inclui tanto compromissos quanto momentos de recolhimento. Antes de aceitar outra tarefa, considere o tempo que você precisa para se recompor e estar presente.'],
  'sun:mercury': ['Dizer o que faz sentido', 'clareza da expressão pessoal', 'Encontrar palavras para uma intenção poderá ajudar você a perceber seus próprios motivos. Ao apresentar uma ideia, observe se está abrindo uma conversa ou procurando aprovação. Explicar um desejo com simplicidade permite que ele seja discutido sem se confundir com seu valor pessoal.', 'Um rascunho poderá revelar o que ainda precisa amadurecer. Releia o que escreveu e deixe espaço para perguntas, inclusive quando tiver bastante convicção sobre o assunto.'],
  'sun:venus': ['Dar lugar ao prazer', 'coerência entre escolhas e valores', 'O que você aprecia poderá dizer bastante sobre a vida que deseja construir. Observe a distância entre aquilo que considera bonito e aquilo a que dedica tempo. Um encontro, uma criação ou um cuidado cotidiano poderá dar expressão concreta a seus valores.', 'Você poderá experimentar uma escolha pequena, feita pelo prazer de realizá-la. Considere também quanto suas preferências dependem do reconhecimento alheio e quanto continuam vivas na intimidade.'],
  'sun:mars': ['Agir com intenção', 'uso da iniciativa pessoal', 'A disposição para agir convida você a escolher uma direção que reconheça como sua. Antes de acelerar, perceba o que deseja defender e o que está apenas provocando uma reação. Uma iniciativa delimitada poderá expressar sua vontade com mais clareza do que vários esforços simultâneos.', 'Se houver divergência, formule um pedido concreto. Isso poderá ajudar a distinguir a firmeza necessária para sustentar uma escolha da pressa de provar que você tem razão.'],
  'sun:jupiter': ['Ampliar a perspectiva', 'proporção das expectativas', 'Imaginar possibilidades maiores poderá devolver sentido a uma tarefa conhecida. Você poderá olhar além do resultado imediato e perguntar o que deseja aprender com essa experiência. Preserve a curiosidade, sem atribuir a uma única oportunidade a obrigação de mudar toda a sua vida.', 'Compare o entusiasmo com o tempo e os recursos disponíveis. Uma expansão que admite etapas deixa espaço para aprender com a prática e reformular o caminho escolhido.'],
  'sun:saturn': ['Assumir o que é seu', 'responsabilidades e limites pessoais', 'Diante de deveres e expectativas, reserve algum tempo para examinar o peso que vem carregando. Algumas exigências poderão ter sentido; outras talvez precisem ser renegociadas. Reconhecer seus limites permite escolher compromissos com mais consciência, sem transformar cada dificuldade em julgamento sobre sua capacidade.', 'Uma conversa objetiva sobre prazos poderá ser mais útil do que uma promessa feita por constrangimento. Dê forma ao que pode oferecer e reconheça o que depende de outras pessoas.'],
  'sun:uranus': ['Abrir espaço para o próprio caminho', 'autonomia nas escolhas', 'A necessidade de experimentar poderá iluminar hábitos que você mantém apenas por costume. Pergunte onde existe espaço para agir de maneira mais coerente com suas ideias. Uma mudança pequena e reversível poderá ajudar a conhecer uma possibilidade antes de reorganizar tudo ao redor dela.', 'Avise quem compartilha os efeitos de suas escolhas. A autonomia ganha consistência quando você também assume a parte prática da liberdade que deseja exercer.'],
  'sun:neptune': ['Escutar sem perder a referência', 'discernimento diante dos ideais', 'O desejo de encontrar sentido poderá aproximar você da arte, do silêncio ou de uma causa. Acolha essa abertura e observe as imagens que projeta sobre pessoas e projetos. Uma impressão pode inspirar, mas ainda precisará de tempo e contato com a realidade para ganhar forma.', 'Reserve algum espaço para criar sem exigir um resultado imediato. Quando houver decisões compartilhadas, procure esclarecer expectativas e distinguir uma intenção generosa de um compromisso possível.'],
  'sun:pluto': ['Escolher com inteireza', 'relação com poder e reconhecimento', 'A maneira como você ocupa espaço poderá merecer um exame mais atento. Observe onde busca reconhecimento e quanto esforço dedica a preservar uma imagem. Admitir motivos contraditórios poderá abrir uma relação mais honesta com suas escolhas, especialmente quando houver autoridade ou influência em jogo.', 'Você não precisa expor tudo para agir com sinceridade. Defina o que deseja compartilhar e respeite o direito de outras pessoas estabelecerem seus próprios limites.'],
  'moon:mercury': ['Encontrar palavras para sentir', 'expressão das necessidades emocionais', 'Uma lembrança ou impressão poderá ganhar contornos mais claros quando você tentar colocá-la em palavras. Escute o que sente sem presumir que isso explica toda a situação. Conversas sobre necessidades cotidianas poderão se beneficiar de exemplos concretos e de perguntas feitas com interesse.', 'Se a conversa ficar confusa, retome um episódio de cada vez. Você poderá descobrir diferenças entre o que foi dito, o que entendeu e aquilo que gostaria de ter recebido.'],
  'moon:venus': ['Cuidar do encontro', 'reciprocidade nos gestos de afeto', 'Pequenos gestos de cuidado poderão ajudar você a perceber como deseja dar e receber afeto. Observe o ambiente, a convivência e os hábitos que tornam um encontro agradável. A vontade de manter a harmonia também merece escuta quando deixa alguma necessidade sua sem palavras.', 'Um convite simples poderá abrir uma conversa sobre preferências. Pergunte o que faz bem à outra pessoa e comunique o que você aprecia, sem esperar que ela adivinhe.'],
  'moon:mars': ['Responder com presença', 'manejo das reações imediatas', 'Sentimentos e impulso de agir poderão se aproximar, convidando você a reconhecer o que está tentando proteger. Antes de responder a uma provocação, perceba qual necessidade ficou exposta. Encontrar uma forma clara de expressá-la poderá evitar que uma contrariedade ocupe toda a conversa.', 'Uma pausa ou uma tarefa manual poderá oferecer distância suficiente para escolher as palavras. Retome o assunto quando conseguir dizer o que deseja sem transformar o outro em adversário.'],
  'moon:jupiter': ['Acolher com medida', 'generosidade na convivência', 'O desejo de acolher poderá ampliar a importância de vínculos, lembranças e costumes familiares. Você poderá encontrar prazer em compartilhar uma refeição ou uma história. Observe, porém, se a generosidade permite que cada pessoa conserve suas preferências e o direito de recusar um convite.', 'Antes de oferecer ajuda, pergunte de que tipo de apoio o outro precisa. Um gesto compatível com suas possibilidades poderá ser mais confortável para todos do que uma grande promessa.'],
  'moon:saturn': ['Dar estrutura ao cuidado', 'limites no cuidado cotidiano', 'Cuidar de alguém ou manter uma rotina poderá trazer perguntas sobre disponibilidade e obrigação. Você poderá reconhecer onde precisa de apoio, descanso ou uma divisão mais clara das tarefas. Levar essas necessidades a sério ajuda a sustentar o cuidado sem exigir uma presença sem limites.', 'Faça acordos que possam ser cumpridos e revistos. Quando o afeto parece depender de estar sempre disponível, conversar sobre responsabilidades poderá devolver espaço para uma convivência mais espontânea.'],
  'moon:uranus': ['Renovar os hábitos', 'liberdade dentro da rotina', 'A relação com hábitos e espaços familiares convida você a experimentar outra maneira de viver o cotidiano. Uma alteração simples poderá mostrar que segurança e novidade podem conviver. Perceba quais costumes ainda oferecem acolhimento e quais continuam apenas porque ninguém pensou em revê-los.', 'Experimente antes de tornar a mudança definitiva. Se você divide a casa ou uma rotina, inclua as necessidades das outras pessoas na escolha do que será reorganizado.'],
  'moon:neptune': ['Dar contorno à sensibilidade', 'limites na escuta emocional', 'Uma escuta sensível poderá revelar nuances que uma conversa apressada deixa passar. Preserve, ao mesmo tempo, a diferença entre perceber um clima e conhecer o que outra pessoa sente. Música, imagens ou escrita poderão oferecer uma linguagem para impressões ainda difíceis de explicar.', 'Pergunte em vez de completar os silêncios com suposições. Você poderá acolher alguém sem assumir a tarefa de resolver tudo o que aparece na relação.'],
  'moon:pluto': ['Escutar o que insiste', 'intensidade dos vínculos e lembranças', 'Uma reação intensa poderá convidar você a olhar com cuidado para necessidades de proteção e pertencimento. Observe o que a situação desperta sem concluir que o passado está se repetindo por inteiro. Dar tempo à compreensão poderá ajudar a separar uma lembrança de uma exigência presente.', 'Respeite seu ritmo para falar de assuntos íntimos. Nas relações próximas, procure formular limites claros e evite usar confidências como argumento para obter uma resposta.'],
  'mercury:venus': ['Conversar com delicadeza', 'escuta e expressão dos afetos', 'A escolha das palavras poderá fazer diferença quando você quiser falar de gostos, acordos ou sentimentos. Procure uma linguagem que preserve a delicadeza e diga o que precisa ser dito. Uma conversa agradável ganha profundidade quando também comporta preferências diferentes e respostas que você não esperava.', 'Você poderá propor um encontro sem distrações ou escrever antes de conversar. Revise sobretudo os trechos em que a vontade de agradar deixa o pedido pouco claro.'],
  'mercury:mars': ['Falar com clareza', 'firmeza na comunicação', 'Uma ideia defendida com convicção poderá ajudar você a sair da indecisão. Observe o ritmo da fala e a disposição para escutar uma objeção. Ao tratar de um assunto difícil, mantenha o foco no problema concreto e deixe espaço para que a outra pessoa termine seu raciocínio.', 'Se perceber que está respondendo apenas para vencer a discussão, retome a pergunta inicial. O esforço mental também poderá encontrar uma aplicação útil na escrita e na resolução de tarefas delimitadas.'],
  'mercury:jupiter': ['Pensar em escala humana', 'relação entre visão e detalhes', 'Uma ideia ampla poderá ganhar vida quando você procurar os exemplos que a sustentam. Aproveite a curiosidade para estudar, comparar perspectivas e fazer perguntas. Antes de apresentar uma conclusão, confira se os detalhes acompanham o entusiasmo e se há espaço para reconhecer o que ainda não sabe.', 'Explique o próximo passo com palavras simples. Um plano que você consegue descrever com clareza poderá ser discutido e corrigido sem perder a ambição que o motivou.'],
  'mercury:saturn': ['Dar precisão às palavras', 'rigor e responsabilidade na comunicação', 'Assuntos que exigem atenção poderão convidar você a organizar o pensamento com paciência. Uma revisão cuidadosa ajuda a reconhecer lacunas e a formular perguntas melhores. Evite transformar a busca de precisão em uma exigência de certeza absoluta antes de dizer qualquer coisa ou começar uma tarefa.', 'Anote o que está combinado e o que ainda depende de confirmação. Em conversas sérias, uma frase direta poderá ser mais acolhedora do que uma explicação longa que deixa o essencial implícito.'],
  'mercury:uranus': ['Experimentar outra pergunta', 'abertura a novas ideias', 'Uma associação inesperada poderá oferecer outro modo de compreender um problema. Dê espaço à inventividade e procure testar o que surge antes de descartar o trabalho anterior. Você poderá aprender bastante ao mudar uma pergunta, comparar métodos ou escutar alguém que raciocina de maneira diferente.', 'Registre as ideias para examiná-las com calma. Ao compartilhar uma proposta, explique a diferença prática que ela faz e permita que outras pessoas apontem dificuldades que você ainda não percebeu.'],
  'mercury:neptune': ['Distinguir impressão de informação', 'clareza entre imaginação e fatos', 'Imagens e intuições poderão enriquecer sua maneira de pensar e escrever. Quando o assunto exigir precisão, procure distinguir o que você observou daquilo que imaginou. Uma pergunta simples ou uma informação conferida poderá dar apoio à sensibilidade sem reduzir a riqueza de uma experiência subjetiva.', 'Na criação, permita que o texto encontre sua forma antes de revisá-lo. Nos acordos cotidianos, confirme o sentido das palavras, sobretudo quando cada pessoa parece entender algo diferente.'],
  'mercury:pluto': ['Investigar sem invadir', 'profundidade e ética da conversa', 'A vontade de compreender o que está por trás de uma resposta poderá sustentar uma investigação cuidadosa. Você poderá se dedicar a um problema complexo ou rever uma explicação aceita por hábito. Preserve a diferença entre fazer perguntas e exigir acesso à intimidade de outra pessoa.', 'Considere quais informações são necessárias para decidir e quais pertencem ao outro. Uma conversa franca precisa de consentimento e de espaço para que uma resposta permaneça incompleta.'],
  'venus:mars': ['Dar voz ao desejo', 'encontro entre desejo e reciprocidade', 'O desejo poderá convidar você a participar mais ativamente de uma relação ou criação. Perceba como expressa interesse e como recebe uma resposta diferente da esperada. A aproximação ganha liberdade quando há clareza sobre preferências e respeito pelo ritmo de cada pessoa envolvida.', 'Você poderá fazer um convite concreto, com espaço real para uma recusa. Em um projeto criativo, experimente dar forma ao impulso antes de decidir se o resultado corresponde ao que imaginou.'],
  'venus:jupiter': ['Celebrar com discernimento', 'prazer e proporção nas escolhas', 'A vontade de desfrutar o que a vida oferece poderá abrir espaço para encontros, arte e generosidade. Observe o que torna uma experiência agradável para você. Escolher com atenção ajuda a preservar o prazer, especialmente quando o entusiasmo convida a prometer ou consumir além do que deseja.', 'Uma celebração simples poderá expressar melhor seus valores do que um gesto feito para impressionar. Considere os recursos disponíveis e a liberdade de cada pessoa participar à sua maneira.'],
  'venus:saturn': ['Cuidar do que permanece', 'compromisso e reciprocidade afetiva', 'A relação entre afeto e compromisso poderá convidar você a observar os gestos que sustentam um vínculo. Consistência, disponibilidade e limites merecem uma conversa concreta. Procure reconhecer o que pode oferecer e o que espera receber, sem tomar uma dificuldade de expressão como medida de todo o sentimento.', 'Acordos afetivos precisam admitir mudanças e diferenças. Se houver uma cobrança recorrente, descreva a situação com clareza e pergunte que compromisso cada pessoa está disposta a assumir.'],
  'venus:uranus': ['Deixar o vínculo respirar', 'autonomia e renovação dos vínculos', 'O desejo de novidade poderá convidar você a rever costumes de uma relação ou preferências estéticas. Observe onde a convivência comporta mais liberdade e curiosidade. Experimentar algo diferente poderá ser enriquecedor quando houver conversa sobre o que cada pessoa deseja e sobre os acordos já existentes.', 'Comece por uma proposta que possa ser discutida. A surpresa pode tornar um encontro agradável, mas decisões que afetam o vínculo pedem participação de quem viverá suas consequências.'],
  'venus:neptune': ['Apreciar sem idealizar', 'expectativas nos afetos e na beleza', 'O encantamento poderá aproximar você da arte e despertar o desejo de uma relação mais sensível. Aproveite a inspiração, observando quanto da experiência pertence ao encontro e quanto nasce de suas expectativas. Conhecer alguém exige tempo, inclusive para perceber diferenças que uma imagem bonita deixa de fora.', 'Pergunte o que está sendo oferecido de fato. Na criação, permita alguma liberdade à imaginação; nos vínculos, preserve limites que ajudem você a estar presente sem se abandonar.'],
  'venus:pluto': ['Ser honesto nos vínculos', 'desejo, confiança e poder nas relações', 'A intensidade de um vínculo poderá trazer perguntas sobre desejos, receios e formas de buscar segurança. Observe se há espaço para discordar e escolher livremente. Uma conversa honesta poderá tornar mais claras as necessidades de cada pessoa, sem fazer do ciúme uma prova de amor.', 'Assuntos delicados merecem tempo e privacidade. Procure falar de sua experiência, respeitar limites e perceber quando a tentativa de preservar a proximidade começa a restringir a liberdade do outro.'],
  'mars:jupiter': ['Empregar o entusiasmo', 'proporção entre iniciativa e ambição', 'A vontade de avançar poderá encontrar novos objetivos e uma disposição para experimentar. Escolha uma tarefa em que o entusiasmo possa ganhar aplicação concreta. Antes de ampliar o esforço, avalie o tamanho do compromisso e reconheça onde a confiança ainda precisa do apoio de preparação.', 'Você poderá dividir uma meta ambiciosa em etapas observáveis. Acompanhar o que acontece entre uma tentativa e outra permite ajustar a estratégia sem depender apenas da força de vontade.'],
  'mars:saturn': ['Sustentar o esforço', 'disciplina e ritmo de trabalho', 'Uma tarefa exigente pede uma combinação de iniciativa e paciência. Observe o que depende de prática, organização ou respeito a um limite real. A constância poderá ser mais útil do que forçar um avanço imediato, sobretudo quando o trabalho precisa continuar depois do entusiasmo inicial.', 'Estabeleça uma etapa possível e um momento para rever o progresso. Se houver resistência, procure entender sua causa antes de aumentar a pressão sobre você ou sobre quem trabalha ao seu lado.'],
  'mars:uranus': ['Mudar com consciência', 'impulso de ruptura e experimentação', 'O desejo de sair de uma situação repetitiva poderá pedir uma resposta inventiva. Você poderá experimentar um método diferente ou recuperar autonomia em uma tarefa. Dê atenção à pressa: uma mudança ganha consistência quando você conhece o que deseja modificar e pode acompanhar seus efeitos.', 'Prefira testar uma alternativa em escala pequena. Ao mudar um procedimento compartilhado, combine a experiência com as pessoas envolvidas e mantenha uma maneira simples de avaliar o resultado.'],
  'mars:neptune': ['Encontrar uma ação possível', 'direção do esforço e motivação', 'Antes de agir, talvez você precise de uma referência mais clara. Pergunte a serviço de quê você está empregando seu esforço e se a tarefa corresponde ao que considera valioso. Uma atividade criativa ou solidária poderá dar forma a uma intenção, desde que seus limites sejam respeitados.', 'Quando a direção ainda parecer vaga, escolha uma ação pequena e verificável. Você poderá reservar tempo para reconsiderar o objetivo antes de assumir uma responsabilidade difícil de delimitar.'],
  'mars:pluto': ['Usar a força com critério', 'persistência e limites na ação', 'A determinação poderá ajudar você a encarar uma tarefa que vinha evitando. Observe quanto esforço ela pede e que efeitos sua maneira de agir produz nas relações. Persistir com consciência inclui reconhecer quando é preciso mudar de estratégia, pedir colaboração ou interromper uma disputa que perdeu o propósito.', 'Defina o objetivo antes de insistir. Se houver conflito, mantenha a atenção nos comportamentos e nos acordos possíveis, respeitando o direito de cada pessoa decidir por si.'],
  'jupiter:saturn': ['Dar sustentação aos planos', 'equilíbrio entre expansão e estrutura', 'Planos de crescimento poderão pedir uma conversa entre desejo e viabilidade. Você poderá examinar o que quer ampliar e quais bases permitem sustentar essa escolha. O limite oferece uma referência útil quando ajuda a definir etapas, responsabilidades e critérios para reconhecer se o caminho ainda faz sentido.', 'Compare o alcance da proposta com os recursos disponíveis. Uma revisão de prioridades poderá preservar o que merece continuidade e tornar mais claro o que ainda precisa de preparação.'],
  'jupiter:uranus': ['Aprender com a experiência', 'liberdade para explorar possibilidades', 'A curiosidade por outros caminhos poderá convidar você a ampliar suas referências. Uma experiência nova, um estudo ou uma conversa poderá questionar certezas antigas. Procure compreender o que essa abertura modifica na prática, sem precisar tratar cada novidade como uma resposta para tudo.', 'Escolha uma hipótese que possa ser testada. Compartilhar o que você está aprendendo, inclusive as dúvidas, poderá criar uma troca mais fértil do que defender uma conclusão ainda provisória.'],
  'jupiter:neptune': ['Examinar o que inspira', 'discernimento diante de crenças e ideais', 'O desejo de acreditar em algo maior poderá aproximar você de uma visão generosa da vida. Observe como essa inspiração se traduz em escolhas concretas. Uma causa, uma prática espiritual ou um projeto merece espaço para perguntas, especialmente quando desperta expectativas difíceis de conferir.', 'Você poderá participar sem abrir mão do próprio discernimento. Procure conhecer os compromissos envolvidos e distinguir o sentido pessoal de uma experiência das afirmações que ela faz sobre o mundo.'],
  'jupiter:pluto': ['Rever a medida da ambição', 'ética no uso da influência', 'A vontade de ampliar sua participação poderá trazer perguntas sobre ambição e influência. Observe quais valores orientam seus objetivos e como eles afetam outras pessoas. Uma convicção se torna mais consistente quando admite exame, sobretudo se estiver sendo usada para justificar decisões que concentram poder.', 'Considere quem participa das escolhas e quem assume suas consequências. Você poderá reformular uma meta para que ela corresponda melhor aos princípios que deseja defender na prática.'],
  'saturn:uranus': ['Reformar com responsabilidade', 'relação entre continuidade e mudança', 'Uma estrutura conhecida poderá ser examinada à luz de necessidades que mudaram. Você poderá reconhecer o que ainda funciona e onde há espaço para experimentar. Rever uma regra ou um processo exige compreender sua função, inclusive para preservar aquilo que oferece apoio enquanto outra forma é testada.', 'Converse sobre os custos e os benefícios de cada alternativa. Uma mudança delimitada poderá produzir informações úteis para decidir o que convém manter, adaptar ou deixar de fazer.'],
  'saturn:neptune': ['Dar forma ao que importa', 'relação entre ideal e compromisso', 'Um ideal poderá pedir tradução em tempo, trabalho e limites concretos. Você poderá perceber a distância entre aquilo que imagina e o que consegue sustentar. Olhar para essa diferença com sobriedade ajuda a escolher uma forma possível de participar de algo que considera valioso.', 'Defina uma responsabilidade que você consiga descrever e cumprir. Quando uma expectativa permanecer vaga, procure esclarecê-la antes de assumir obrigações em nome de um propósito compartilhado.'],
  'saturn:pluto': ['Examinar as estruturas', 'responsabilidade e relações de poder', 'A relação com regras, deveres e autoridade poderá convidar você a uma revisão cuidadosa. Observe quais estruturas oferecem apoio e quais exigem esforço apenas para permanecer iguais. Mudanças consistentes pedem atenção às responsabilidades envolvidas e às pessoas que dependem dos acordos em discussão.', 'Escolha um procedimento concreto para examinar. Identificar quem decide, quem executa e como uma decisão pode ser revista poderá tornar a conversa sobre poder menos abstrata.'],
  'uranus:neptune': ['Imaginar outras formas de participar', 'renovação das ideias coletivas', 'Ideias de liberdade e pertencimento poderão ser pensadas em conjunto. Você poderá observar como imagens de futuro orientam suas escolhas e que espaço deixam para diferenças. Experimentações culturais ou criativas oferecem um campo para explorar essas perguntas sem exigir que uma visão esteja pronta para todos.', 'Procure projetos nos quais seja possível aprender e fazer perguntas. A abertura a novas linguagens poderá conviver com uma avaliação cuidadosa do que cada proposta pede de seus participantes.'],
  'uranus:pluto': ['Participar da mudança', 'autonomia diante das estruturas coletivas', 'A relação entre liberdade e poder poderá servir de lente para observar grupos, instituições e hábitos compartilhados. Você poderá perguntar onde suas escolhas têm alcance concreto. Reconhecer esse alcance ajuda a participar de mudanças com responsabilidade, sem atribuir a uma pessoa a tarefa de resolver tensões coletivas.', 'Examine como as decisões são tomadas nos espaços de que você participa. Uma proposta clara, discutida com quem será afetado, poderá abrir possibilidades mais consistentes de reorganização.'],
  'neptune:pluto': ['Aprofundar o sentido da participação', 'valores compartilhados e imaginação coletiva', 'As imagens que uma sociedade cultiva oferecem uma referência para refletir sobre seus próprios valores. Observe que histórias orientam sua compreensão de pertencimento, perda e renovação. Arte, estudo e escuta oferecem maneiras de explorar esses temas sem transformar uma interpretação simbólica em certeza sobre o destino coletivo.', 'Você poderá aproximar a reflexão de uma escolha cotidiana, como a forma de participar de um grupo. Preserve a abertura para perspectivas que revelem aspectos deixados de fora por sua primeira leitura.'],
};

