function compose(material: Material, nuance: string, kind: ReadingKind, sourceKeys: string[], continuation?: string, overview?: string): AstroReading {
  const [theme, focus, text, extra] = material;
  return { theme, focus, lead: text, nuance, overview: overview ?? `${theme.toLocaleLowerCase('pt-BR').replace(/^./, letter => letter.toLocaleUpperCase('pt-BR'))} poderá ser uma forma de refletir sobre ${focus}.`,
    paragraphs: kind === 'day' ? [`${text} ${nuance}`] : [`${text} ${nuance}`, `${extra}${continuation ? ` ${continuation}` : ''}`], sourceKeys };
}

export function astroReading(event: ReportEvent, kind: ReadingKind): AstroReading {
  const [type, first, second, third] = event.catalogKey.split(':');
  if (type !== event.kind) throw new RangeError(`Inconsistent editorial event: ${event.catalogKey}`);
  if (type === 'aspect') {
    const ordered = [first!, second!].sort((a, b) => REPORT_BODIES.indexOf(a as typeof REPORT_BODIES[number]) - REPORT_BODIES.indexOf(b as typeof REPORT_BODIES[number]));
    const key = ordered.join(':');
    const material = pairs[key];
    const variants = aspect[third!];
    const variant = Object.keys(pairs).indexOf(key) % 5;
    const nuance = variants?.[variant];
    if (!material || !nuance) throw new RangeError(`Missing astro editorial: ${event.catalogKey}`);
    return compose(material, nuance, kind, [`astro:pair:${key}`, `astro:aspect:${third}`, `astro:aspect:${third}:variant:${variant + 1}`], undefined, pairOverviews[key]);
  }
  if (type === 'station') {
    const body = bodies[first!];
    if (!body || !['direct', 'retrograde'].includes(second!)) throw new RangeError(`Missing astro editorial: ${event.catalogKey}`);
    const direct = second === 'direct';
    return compose([stationThemes[first!]?.[direct ? 1 : 0] ?? (direct ? 'Retomar com atenção' : 'Rever antes de insistir'), body[1], body[2], body[3]],
      direct ? 'Você poderá reconsiderar o que deseja colocar em prática, respeitando o tempo necessário para assimilar uma revisão.' : 'A revisão convida você a reconsiderar seus motivos e a escutar o que uma pausa permite compreender.',
      kind, [`astro:body:${first}`, `astro:station:${second}`, `astro:overview:body:${first}`], undefined, bodyOverviews[first!]);
  }
  const signNumber = Number(type === 'sign' || type === 'retrograde' ? second : third ?? second);
  // Phase/eclipse keys contain their sign as the third component.
  const sign = signs[signNumber];
  if (!Number.isInteger(signNumber) || !sign) throw new RangeError(`Missing astro editorial sign: ${event.catalogKey}`);
  if (type === 'sign' || type === 'retrograde') {
    const body = bodies[first!];
    if (!body) throw new RangeError(`Missing astro editorial body: ${event.catalogKey}`);
    const review = type === 'retrograde' ? retrograde[first!] : undefined;
    if (type === 'retrograde' && !review) throw new RangeError(`Missing astro retrograde editorial: ${event.catalogKey}`);
    const material: Material = [type === 'retrograde' ? stationThemes[first!]?.[0] ?? 'Rever escolhas e prioridades' : sign[0], `${body[1]} e ${sign[1]}`, review ?? body[2], body[3]];
    return compose(material, sign[2], kind, [`astro:body:${first}`, `astro:sign:${signNumber}`, ...(type === 'retrograde' ? [`astro:retrograde:${first}`] : [])], type === 'retrograde' ? 'Ao rever uma escolha, procure compreender o que mudou em suas prioridades antes de repetir uma resposta conhecida.' : undefined, bodyOverviews[first!]);
  }
  const material = type === 'phase' ? phases[first!] : type === 'eclipse' ? eclipses[first!] : undefined;
  if (!material) throw new RangeError(`Missing astro editorial: ${event.catalogKey}`);
  return compose(material, sign[2], kind, [`astro:${type}:${first}`, `astro:sign:${signNumber}`]);
}
